//! The user's installed Codex CLI through its official app-server protocol.
//!
//! The bridge speaks the JSON-RPC subset of `codex app-server` (stdio, one JSON
//! object per line) generated by `codex app-server generate-ts` for codex-cli
//! 0.166.0. The child runs in a dedicated `CODEX_HOME` and working directory
//! under app data, with a scrubbed environment, Codex's own shell, file, web,
//! plugin and MCP tools disabled, a read-only sandbox, and every approval
//! request declined. Database tools reach it only as dynamic tools answered by
//! the application's existing gated executor.
mod args;
mod login;
mod process;
mod provider;
mod rpc;
mod session;
mod status;
mod version;

pub use provider::CodexProvider;
pub use status::{AccountMode, CodexStatus};
pub use version::TESTED_VERSION;

use crate::{AiError, Model, ProviderConfig, ProviderKind, RequestOptions};
use std::path::PathBuf;
use tokio::sync::oneshot;

/// A saved Codex provider resolved to an executable and a dedicated app-data root.
#[derive(Clone, Debug)]
pub struct Bridge {
    configured: String,
    root: PathBuf,
}
impl Bridge {
    /// Build without probing; `root` is a dedicated directory under app data.
    /// # Errors
    /// Rejects non-Codex or invalid provider settings.
    pub fn new(config: &ProviderConfig, root: PathBuf) -> Result<Self, AiError> {
        if config.kind != ProviderKind::Codex || !root.is_absolute() {
            return Err(AiError::InvalidConfig);
        }
        config.validate()?;
        Ok(Self {
            configured: config.base_url.clone(),
            root,
        })
    }
    /// Discovery, version check and the CLI's own account state; never a prompt.
    /// Models are listed only for a signed-in account.
    pub async fn status(&self, options: &RequestOptions) -> (CodexStatus, Vec<Model>) {
        status::probe(self, options).await
    }
    /// Start the CLI's own `ChatGPT` sign-in. The browser URL is sent once to
    /// `url`; the returned state is re-read from the CLI after completion.
    /// # Errors
    /// Missing/unsupported CLI, cancellation, timeout or a failed sign-in.
    pub async fn login(
        &self,
        options: &RequestOptions,
        url: oneshot::Sender<String>,
    ) -> Result<CodexStatus, AiError> {
        login::login(self, options, url).await
    }
    fn launch(&self) -> Result<process::Launch, AiError> {
        let executable = process::locate(&self.configured).ok_or(AiError::Unsupported)?;
        Ok(process::Launch::new(executable, self.root.clone()))
    }
}
